const topics=[
{id:"T1",title:"Transversal descriptivo",goal:"¿Cómo se distribuyen las características de una muestra evaluada una sola vez?",dest:"Frecuencias, porcentajes, media y desviación estándar o mediana y rango intercuartílico.",pilot:true},
{id:"T2",title:"Transversal analítico: asociación",goal:"¿Se asocia una característica con un desenlace categórico?",dest:"Chi-cuadrado o prueba exacta de Fisher; medida de asociación transversal e intervalo."},
{id:"T3",title:"Transversal analítico: correlación",goal:"¿Cómo varían juntas dos mediciones cuantitativas u ordinales?",dest:"Correlación de Pearson o de Spearman según variables y patrón observado."},
{id:"T4",title:"Cohorte con seguimiento fijo",goal:"¿Los grupos tienen distinta ocurrencia de un evento durante seguimiento comparable?",dest:"Incidencia acumulada, razón de riesgos (RR) y diferencia de riesgos."},
{id:"T5",title:"Casos y controles",goal:"¿Fue más frecuente la exposición entre los casos que entre los controles?",dest:"Razón de momios (OR), interpretada según el muestreo."},
{id:"T6",title:"Tiempo hasta el evento",goal:"¿Difiere el tiempo hasta el evento entre grupos?",dest:"Kaplan-Meier y log-rank; Cox con HR si se sostienen los supuestos."},
{id:"T7",title:"Cuasiexperimental: un grupo antes y después",goal:"¿Cambió el desenlace en las mismas personas después de la intervención?",dest:"t de Student relacionada o rangos con signo de Wilcoxon."},
{id:"T8",title:"Cuasiexperimental: dos grupos",goal:"¿Difiere el desenlace entre el grupo intervenido y el de comparación?",dest:"t de Welch o U de Mann-Whitney; con pre/post y control, ANCOVA o diferencia en diferencias."},
{id:"T9",title:"Ensayo aleatorizado de dos brazos",goal:"¿Qué efecto tiene la intervención frente al control en el desenlace primario?",dest:"Contraste entre brazos, con ajuste basal cuando corresponda; hipótesis según protocolo."},
{id:"T10",title:"Ensayo aleatorizado de tres brazos",goal:"¿Difiere el cambio entre control, dosis baja y dosis alta?",dest:"ANOVA mixta o modelo longitudinal con interacción grupo por tiempo."}
];
