Object.entries(trees).forEach(([topicId,questions])=>questions.forEach((question,qi)=>question[1].forEach((option,oi)=>{
 const sentenceCount=(option[1].match(/[.!?](?:\s|$)/g)||[]).length;
 if(sentenceCount<2)option[1]+=" "+feedbackClosers[(qi+oi+Number(topicId.slice(1)))%feedbackClosers.length];
})));
const rng=(()=>{let s=8122026;return()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296;};})();
const people=Array.from({length:24},(_,i)=>({id:"E"+String(i+1).padStart(2,"0"),edad_anios:22+Math.floor(rng()*39),sexo_registrado:rng()<.58?"Mujer":"Hombre",turno:rng()<.64?"Día":"Noche",imc_kg_m2:+(19.2+rng()*13.1).toFixed(1),prension_kg:+(17+rng()*27).toFixed(1),caminata_6min_m:Math.round(355+rng()*330),actividad_fisica:["Bajo","Moderado","Alto"][Math.min(2,Math.floor(rng()*3))]}));
function median(a){a=[...a].sort((x,y)=>x-y);return a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2;}
function quant(a){const mean=a.reduce((s,x)=>s+x,0)/a.length,sd=Math.sqrt(a.reduce((s,x)=>s+(x-mean)**2,0)/(a.length-1)),sorted=[...a].sort((x,y)=>x-y);return{n:a.length,mean:mean,sd:sd,median:median(a),q1:median(sorted.slice(0,12)),q3:median(sorted.slice(12)),min:Math.min(...a),max:Math.max(...a)};}
const stats={edad_anios:quant(people.map(x=>x.edad_anios)),imc_kg_m2:quant(people.map(x=>x.imc_kg_m2)),caminata_6min_m:quant(people.map(x=>x.caminata_6min_m))};
function freq(key){const c={};people.forEach(p=>c[p[key]]=(c[p[key]]||0)+1);return Object.keys(c).map(k=>[k,c[k],c[k]/people.length*100]);}
function h(s){return String(s).replace(/[&<>\"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
function f(n,d=1){return new Intl.NumberFormat("es-CO",{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);}
function table(head,rows){return '<div class="table-wrap"><table class="data-table"><thead><tr>'+head.map(x=>'<th scope="col">'+x+'</th>').join("")+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join("")+'</tr>').join("")+'</tbody></table></div>';}
const grid=document.getElementById("moduleGrid"),summary=document.getElementById("moduleSummary"),tabs=document.getElementById("moduleTabs"),content=document.getElementById("moduleContent");
let current="T1",section=0,route={i:0,history:[],feedback:null,result:null,selected:null};
function drawCards(){grid.innerHTML=topics.map(t=>'<button class="module-card" type="button" data-id="'+t.id+'" aria-pressed="'+(current===t.id)+'"><span class="module-state '+(t.pilot?"ready":"")+'">'+(t.pilot?"piloto":"ruta")+'</span><span class="module-id">'+t.id+'</span><strong>'+h(t.title)+'</strong><span>'+h(t.goal)+'</span></button>').join("");grid.querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>chooseTopic(b.dataset.id,true));}
function chooseTopic(id,scroll){current=id;section=id==="T1"?0:4;route={i:0,history:[],feedback:null,result:null,selected:null};drawCards();drawModule();if(scroll)document.getElementById("piloto").scrollIntoView({behavior:"smooth"});}
function drawModule(){const t=topics.find(x=>x.id===current);summary.innerHTML='<p class="eyebrow">'+t.id+' · '+(t.pilot?"piloto con datos":"ruta y guía pedagógica")+'</p><h3>'+h(t.title)+'</h3><p>'+h(t.goal)+'</p><div class="summary-meta"><div><b>Análisis de destino</b><br>'+h(t.dest)+'</div><div><b>Estado</b><br>'+(t.pilot?"12 secciones y base sintética disponible":"12 secciones con guía SPSS/jamovi, árbol y límites metodológicos")+'</div></div>';tabs.innerHTML=labels.map((x,i)=>'<button type="button" role="tab" id="tab'+i+'" aria-selected="'+(section===i)+'" aria-controls="moduleContent" tabindex="'+(section===i?0:-1)+'" class="module-tab" data-section="'+i+'">'+String(i+1).padStart(2,"0")+' '+h(x)+'</button>').join("");tabs.querySelectorAll("[data-section]").forEach(b=>b.onclick=()=>{section=+b.dataset.section;drawModule();content.focus({preventScroll:true});});drawSection();}
